let bad =EmailEvents
| where Timestamp {Lookback}
| where (isempty("{SenderFromAddress}") or SenderFromAddress contains "{SenderFromAddress}")
| where (isempty("{Subject}") or Subject contains "{Subject}")
| where EmailDirection in ("Inbound", "IntraOrg")
| distinct NetworkMessageId;
UrlClickEvents
| where Timestamp {Lookback}
| where NetworkMessageId in (bad)

DeviceNetworkEvents
// Filter for any browsers opening a URL in their process command line or look directly at the remote url contacted
| where InitiatingProcessCommandLine contains "{FinalLink}" or RemoteUrl contains "{FinalLink}"
// Filter for successful connections
| where ActionType == "ConnectionSuccess"
// Only show non system/service related connections
| where isnotempty(InitiatingProcessAccountUpn)

let initial_click =UrlClickEvents
| where Url has "{URL}"
| project Timestamp, AccountUpn, AppName, ActionType, Url
| distinct AccountUpn;
DeviceNetworkEvents
// Filter for any browsers opening a URL in their process command line or look directly at the remote url contacted
| where InitiatingProcessCommandLine contains "{FinalLink}" or RemoteUrl contains "{FinalLink}"
// Filter for successful connections
| where ActionType == "ConnectionSuccess"
// Only show non system/service related connections
| where isnotempty(InitiatingProcessAccountUpn)
| where InitiatingProcessAccountUpn in (initial_click)

let initial_click =UrlClickEvents
| where Url has "{URL}"
| project Timestamp, AccountUpn, AppName, ActionType, Url
| distinct AccountUpn;
DeviceNetworkEvents
// Filter for any browsers opening a URL in their process command line or look directly at the remote url contacted
| where InitiatingProcessCommandLine contains "{FinalLink}" or RemoteUrl contains "{FinalLink}"
// Filter for successful connections
| where ActionType == "ConnectionSuccess"
// Only show non system/service related connections
| where isnotempty(InitiatingProcessAccountUpn)
| where InitiatingProcessAccountUpn !in (initial_click)

DeviceProcessEvents
| where Timestamp {InvestigationTimeline}
| where InitiatingProcessCommandLine contains "microsoft.com" or ProcessCommandLine contains "microsoft.com"
